WITH cohort AS ((SELECT replaceOne(patient_unique_id, 'msk_chord_2024_', '') AS pid, replaceOne(sample_unique_id, 'msk_chord_2024_', '') AS sid FROM snapshot_db.sample_derived
  WHERE cancer_study_identifier = 'msk_chord_2024'
    AND (('sample', replaceOne(sample_unique_id, 'msk_chord_2024_', '')) IN (SELECT DISTINCT type AS lvl, if(type = 'sample', replaceOne(sample_unique_id, 'msk_chord_2024_', ''), replaceOne(patient_unique_id, 'msk_chord_2024_', '')) AS id
  FROM (SELECT internal_id, sample_unique_id, patient_unique_id, attribute_name, attribute_value, cancer_study_identifier, type
   FROM snapshot_db.clinical_data_derived WHERE lowerUTF8(trimBoth(attribute_value)) NOT IN ('', 'na', 'n/a', 'nan'))
  WHERE cancer_study_identifier = 'msk_chord_2024'
    AND attribute_name = 'CANCER_TYPE' AND lowerUTF8(trimBoth(attribute_value)) IN (lowerUTF8(trimBoth('Colorectal Cancer')))) OR ('patient', replaceOne(patient_unique_id, 'msk_chord_2024_', '')) IN (SELECT DISTINCT type AS lvl, if(type = 'sample', replaceOne(sample_unique_id, 'msk_chord_2024_', ''), replaceOne(patient_unique_id, 'msk_chord_2024_', '')) AS id
  FROM (SELECT internal_id, sample_unique_id, patient_unique_id, attribute_name, attribute_value, cancer_study_identifier, type
   FROM snapshot_db.clinical_data_derived WHERE lowerUTF8(trimBoth(attribute_value)) NOT IN ('', 'na', 'n/a', 'nan'))
  WHERE cancer_study_identifier = 'msk_chord_2024'
    AND attribute_name = 'CANCER_TYPE' AND lowerUTF8(trimBoth(attribute_value)) IN (lowerUTF8(trimBoth('Colorectal Cancer'))))))),
altered AS (
  SELECT g.hugo_gene_symbol AS gene, replaceOne(g.sample_unique_id, 'msk_chord_2024_', '') AS sid, g.variant_type AS vtype,
         max(ann.is_driver) AS is_driver
  FROM snapshot_db.genomic_event_derived g
  LEFT JOIN oncokb_annotation.variant_annotation ann
    ON ann.oncokb_version = 'v7.5' AND ann.is_driver
   AND ann.hugo_gene_symbol = g.hugo_gene_symbol
   AND ((g.variant_type = 'mutation' AND ann.alteration_type = 'MUTATION' AND ann.alteration = g.mutation_variant)
     OR (g.variant_type = 'cna' AND ann.alteration_type = 'CNA' AND ann.alteration = if(g.cna_alteration >= 2, 'AMPLIFICATION', 'DELETION'))
     OR (g.variant_type = 'structural_variant' AND ann.alteration_type = 'SV' AND ann.alteration = 'Fusion'))
  WHERE g.cancer_study_identifier = 'msk_chord_2024'
    AND g.hugo_gene_symbol IN ('ABL1','EGFR','ERBB2','ERBB3','ERBB4','PDGFRA','PDGFRB','MET','FGFR1','FGFR2','FGFR3','FGFR4','FLT3','ALK','RET','ROS1','KIT','IGF1R','NTRK1','NTRK2','NTRK3','SOS1','GRB2','PTPN11','KRAS','HRAS','NRAS','RIT1','ARAF','BRAF','RAF1','RAC1','MAP2K1','MAP2K2','MAPK1','NF1','RASA1','CBL','ERRFI1','CBLB','CBLC','INSR','INSRR','IRS1','SOS2','SHC1','SHC2','SHC3','SHC4','RASGRP1','RASGRP2','RASGRP3','RASGRP4','RAPGEF1','RAPGEF2','RASGRF1','RASGRF2','FNTA','FNTB','RCE1','ICMT','MRAS','PLXNB1','MAPK3','ARHGAP35','RASA2','RASA3','RASAL1','RASAL2','RASAL3','SPRED1','SPRED2','SPRED3','DAB2IP','SHOC2','PPP1CA','SCRIB','PIN1','KSR1','KSR2','PEBP1','ERF','PEA15','JAK2','IRS2','EIF4EBP1','AKT1','AKT2','AKT3','AKT1S1','DEPDC5','DEPTOR','INPP4B','MAPKAP1','MLST8','MTOR','NPRL2','NPRL3','PDK1','PIK3CA','PIK3CB','PIK3R1','PIK3R2','PIK3R3','PPP2R1A','PTEN','RHEB','RICTOR','RPTOR','RPS6','RPS6KB1','STK11','TSC1','TSC2','TP53','MDM2','MDM4','ATM','CHEK2','RPS6KA3','CDKN1A','CDKN1B','CDKN2A','CDKN2B','CDKN2C','CCND1','CCND2','CCND3','CCNE1','CDK2','CDK4','CDK6','RB1','E2F1','E2F3','MAX','MGA','MLX','MLXIP','MLXIPL','MNT','MXD1','MXD3','MXD4','MXI1','MYC','MYCL','MYCN','CHD8','LEF1','LGR4','LGR5','LRP5','LRP6','LZTR1','NDP','PORCN','RSPO1','SFRP1','SFRP2','SFRP4','SFRP5','SOST','TCF7L1','TLE1','TLE2','TLE3','TLE4','WIF1','ZNRF3','CTNNB1','DVL1','DVL2','DVL3','FRAT1','FRAT2','FZD1','FZD10','FZD2','FZD3','FZD4','FZD5','FZD6','FZD7','FZD8','FZD9','WNT1','WNT10A','WNT10B','WNT11','WNT16','WNT2','WNT3A','WNT4','WNT5A','WNT5B','WNT6','WNT7A','WNT7B','WNT8A','WNT8B','WNT9A','WNT9B','AMER1','APC','AXIN1','AXIN2','DKK1','DKK2','DKK3','DKK4','GSK3B','RNF43','TCF7','TCF7L2','CHD4','ARRDC1','CNTN6','CREBBP','EP300','HES1','HES2','HES3','HES4','HES5','HEY1','HEY2','HEYL','KAT2B','KDM5A','NOTCH1','NOTCH2','NOTCH3','NOTCH4','NOV','NRARP','PSEN2','LFNG','ITCH','NCSTN','SPEN','JAG1','APH1A','FBXW7','FHL1','THBS2','HDAC2','MFAP2','CUL1','RFNG','NCOR1','NCOR2','MFAP5','HDAC1','NUMB','JAG2','MAML3','MFNG','CIR1','CNTN1','MAML1','MAML2','NUMBL','PSEN1','PSENEN','RBPJ','RBPJL','RBX1','SAP30','SKP1','SNW1','CTBP1','CTBP2','ADAM10','APH1B','ADAM17','DLK1','DLL1','DLL3','DLL4','DNER','DTX1','DTX2','DTX3','DTX3L','DTX4','EGFL7','STK4','STK3','SAV1','LATS1','LATS2','MOB1A','MOB1B','YAP1','WWTR1','TEAD1','TEAD2','TEAD3','TEAD4','PTPN14','NF2','WWC1','TAOK1','TAOK2','TAOK3','CRB1','CRB2','CRB3','LLGL1','LLGL2','HMCN1','HIPK2','FAT1','FAT2','FAT3','FAT4','DCHS1','DCHS2','CSNK1E','CSNK1D','AJUBA','LIMD1','WTIP','TGFBR1','TGFBR2','ACVR2A','ACVR1B','SMAD2','SMAD3','SMAD4','NFE2L2','KEAP1','CUL3') AND ((g.variant_type != 'cna' OR abs(g.cna_alteration) >= 2) AND NOT g.off_panel)
    AND replaceOne(g.sample_unique_id, 'msk_chord_2024_', '') IN (SELECT sid FROM cohort)
  GROUP BY gene, sid, vtype
),
covered AS (
  SELECT DISTINCT pg.gene AS gene, replaceOne(sp.sample_unique_id, 'msk_chord_2024_', '') AS sid,
         multiIf(sp.alteration_type = 'MUTATION_EXTENDED', 'mutation',
                 sp.alteration_type = 'COPY_NUMBER_ALTERATION', 'cna', 'structural_variant') AS vtype
  FROM snapshot_db.sample_to_gene_panel_derived sp
  JOIN snapshot_db.gene_panel_to_gene_derived pg ON pg.gene_panel_id = sp.gene_panel_id AND pg.gene IN ('ABL1','EGFR','ERBB2','ERBB3','ERBB4','PDGFRA','PDGFRB','MET','FGFR1','FGFR2','FGFR3','FGFR4','FLT3','ALK','RET','ROS1','KIT','IGF1R','NTRK1','NTRK2','NTRK3','SOS1','GRB2','PTPN11','KRAS','HRAS','NRAS','RIT1','ARAF','BRAF','RAF1','RAC1','MAP2K1','MAP2K2','MAPK1','NF1','RASA1','CBL','ERRFI1','CBLB','CBLC','INSR','INSRR','IRS1','SOS2','SHC1','SHC2','SHC3','SHC4','RASGRP1','RASGRP2','RASGRP3','RASGRP4','RAPGEF1','RAPGEF2','RASGRF1','RASGRF2','FNTA','FNTB','RCE1','ICMT','MRAS','PLXNB1','MAPK3','ARHGAP35','RASA2','RASA3','RASAL1','RASAL2','RASAL3','SPRED1','SPRED2','SPRED3','DAB2IP','SHOC2','PPP1CA','SCRIB','PIN1','KSR1','KSR2','PEBP1','ERF','PEA15','JAK2','IRS2','EIF4EBP1','AKT1','AKT2','AKT3','AKT1S1','DEPDC5','DEPTOR','INPP4B','MAPKAP1','MLST8','MTOR','NPRL2','NPRL3','PDK1','PIK3CA','PIK3CB','PIK3R1','PIK3R2','PIK3R3','PPP2R1A','PTEN','RHEB','RICTOR','RPTOR','RPS6','RPS6KB1','STK11','TSC1','TSC2','TP53','MDM2','MDM4','ATM','CHEK2','RPS6KA3','CDKN1A','CDKN1B','CDKN2A','CDKN2B','CDKN2C','CCND1','CCND2','CCND3','CCNE1','CDK2','CDK4','CDK6','RB1','E2F1','E2F3','MAX','MGA','MLX','MLXIP','MLXIPL','MNT','MXD1','MXD3','MXD4','MXI1','MYC','MYCL','MYCN','CHD8','LEF1','LGR4','LGR5','LRP5','LRP6','LZTR1','NDP','PORCN','RSPO1','SFRP1','SFRP2','SFRP4','SFRP5','SOST','TCF7L1','TLE1','TLE2','TLE3','TLE4','WIF1','ZNRF3','CTNNB1','DVL1','DVL2','DVL3','FRAT1','FRAT2','FZD1','FZD10','FZD2','FZD3','FZD4','FZD5','FZD6','FZD7','FZD8','FZD9','WNT1','WNT10A','WNT10B','WNT11','WNT16','WNT2','WNT3A','WNT4','WNT5A','WNT5B','WNT6','WNT7A','WNT7B','WNT8A','WNT8B','WNT9A','WNT9B','AMER1','APC','AXIN1','AXIN2','DKK1','DKK2','DKK3','DKK4','GSK3B','RNF43','TCF7','TCF7L2','CHD4','ARRDC1','CNTN6','CREBBP','EP300','HES1','HES2','HES3','HES4','HES5','HEY1','HEY2','HEYL','KAT2B','KDM5A','NOTCH1','NOTCH2','NOTCH3','NOTCH4','NOV','NRARP','PSEN2','LFNG','ITCH','NCSTN','SPEN','JAG1','APH1A','FBXW7','FHL1','THBS2','HDAC2','MFAP2','CUL1','RFNG','NCOR1','NCOR2','MFAP5','HDAC1','NUMB','JAG2','MAML3','MFNG','CIR1','CNTN1','MAML1','MAML2','NUMBL','PSEN1','PSENEN','RBPJ','RBPJL','RBX1','SAP30','SKP1','SNW1','CTBP1','CTBP2','ADAM10','APH1B','ADAM17','DLK1','DLL1','DLL3','DLL4','DNER','DTX1','DTX2','DTX3','DTX3L','DTX4','EGFL7','STK4','STK3','SAV1','LATS1','LATS2','MOB1A','MOB1B','YAP1','WWTR1','TEAD1','TEAD2','TEAD3','TEAD4','PTPN14','NF2','WWC1','TAOK1','TAOK2','TAOK3','CRB1','CRB2','CRB3','LLGL1','LLGL2','HMCN1','HIPK2','FAT1','FAT2','FAT3','FAT4','DCHS1','DCHS2','CSNK1E','CSNK1D','AJUBA','LIMD1','WTIP','TGFBR1','TGFBR2','ACVR2A','ACVR1B','SMAD2','SMAD3','SMAD4','NFE2L2','KEAP1','CUL3')
  WHERE sp.cancer_study_identifier = 'msk_chord_2024'
    AND sp.alteration_type IN ('MUTATION_EXTENDED','COPY_NUMBER_ALTERATION','STRUCTURAL_VARIANT')
    AND replaceOne(sp.sample_unique_id, 'msk_chord_2024_', '') IN (SELECT sid FROM cohort)
),
raw AS (
  SELECT gene, sid, vtype, max(is_alt) AS is_alt, max(is_drv) AS is_drv
  FROM (
    SELECT gene, sid, vtype, 1 AS is_alt, is_driver > 0 AS is_drv FROM altered
    UNION ALL
    SELECT gene, sid, vtype, 0 AS is_alt, 0 AS is_drv FROM covered
  )
  GROUP BY gene, sid, vtype
),
perSample AS (
  SELECT gene, sid, max(is_alt) AS is_alt, max(is_drv) AS is_drv
  FROM raw GROUP BY gene, sid
)
SELECT gene, vtype,
       uniqExact(sid) AS profiled, uniqExactIf(sid, is_alt = 1) AS altered, uniqExactIf(sid, is_drv = 1) AS driver
FROM raw GROUP BY gene, vtype
UNION ALL
SELECT gene, 'any' AS vtype,
       uniqExact(sid) AS profiled, uniqExactIf(sid, is_alt = 1) AS altered, uniqExactIf(sid, is_drv = 1) AS driver
FROM perSample GROUP BY gene

