  JOIN snapshot_db.gene_panel_to_gene_derived pg ON pg.gene_panel_id = sp.gene_panel_id AND pg.gene IN ('ABL1','EGFR','ERBB2','ERBB3','ERBB4','PDGFRA','PDGFRB','MET','FGFR1','FGFR2','FGFR3','FGFR4','FLT3','ALK','RET','ROS1','KIT','IGF1R','NTRK1','NTRK2','NTRK3','SOS1','GRB2','PTPN11','KRAS','HRAS','NRAS','RIT1','ARAF','BRAF','RAF1','RAC1','MAP2K1','MAP2K2','MAPK1','NF1','RASA1','CBL','ERRFI1','CBLB','CBLC','INSR','INSRR','IRS1','SOS2','SHC1','SHC2','SHC3','SHC4','RASGRP1','RASGRP2','RASGRP3','RASGRP4','RAPGEF1','RAPGEF2','RASGRF1','RASGRF2','FNTA','FNTB','RCE1','ICMT','MRAS','PLXNB1','MAPK3','ARHGAP35','RASA2','RASA3','RASAL1','RASAL2','RASAL3','SPRED1','SPRED2','SPRED3','DAB2IP','SHOC2','PPP1CA','SCRIB','PIN1','KSR1','KSR2','PEBP1','ERF','PEA15','JAK2','IRS2','EIF4EBP1','AKT1','AKT2','AKT3','AKT1S1','DEPDC5','DEPTOR','INPP4B','MAPKAP1','MLST8','MTOR','NPRL2','NPRL3','PDK1','PIK3CA','PIK3CB','PIK3R1','PIK3R2','PIK3R3','PPP2R1A','PTEN','RHEB','RICTOR','RPTOR','RPS6','RPS6KB1','STK11','TSC1','TSC2','TP53','MDM2','MDM4','ATM','CHEK2','RPS6KA3','CDKN1A','CDKN1B','CDKN2A','CDKN2B','CDKN2C','CCND1','CCND2','CCND3','CCNE1','CDK2','CDK4','CDK6','RB1','E2F1','E2F3','MAX','MGA','MLX','MLXIP','MLXIPL','MNT','MXD1','MXD3','MXD4','MXI1','MYC','MYCL','MYCN','CHD8','LEF1','LGR4','LGR5','LRP5','LRP6','LZTR1','NDP','PORCN','RSPO1','SFRP1','SFRP2','SFRP4','SFRP5','SOST','TCF7L1','TLE1','TLE2','TLE3','TLE4','WIF1','ZNRF3','CTNNB1','DVL1','DVL2','DVL3','FRAT1','FRAT2','FZD1','FZD10','FZD2','FZD3','FZD4','FZD5','FZD6','FZD7','FZD8','FZD9','WNT1','WNT10A','WNT10B','WNT11','WNT16','WNT2','WNT3A','WNT4','WNT5A','WNT5B','WNT6','WNT7A','WNT7B','WNT8A','WNT8B','WNT9A','WNT9B','AMER1','APC','AXIN1','AXIN2','DKK1','DKK2','DKK3','DKK4','GSK3B','RNF43','TCF7','TCF7L2','CHD4','ARRDC1','CNTN6','CREBBP','EP300','HES1','HES2','HES3','HES4','HES5','HEY1','HEY2','HEYL','KAT2B','KDM5A','NOTCH1','NOTCH2','NOTCH3','NOTCH4','NOV','NRARP','PSEN2','LFNG','ITCH','NCSTN','SPEN','JAG1','APH1A','FBXW7','FHL1','T