','JAG2','MAML3','MFNG','CIR1','CNTN1','MAML1','MAML2','NUMBL','PSEN1','PSENEN','RBPJ','RBPJL','RBX1','SAP30','SKP1','SNW1','CTBP1','CTBP2','ADAM10','APH1B','ADAM17','DLK1','DLL1','DLL3','DLL4','DNER','DTX1','DTX2','DTX3','DTX3L','DTX4','EGFL7','STK4','STK3','SAV1','LATS1','LATS2','MOB1A','MOB1B','YAP1','WWTR1','TEAD1','TEAD2','TEAD3','TEAD4','PTPN14','NF2','WWC1','TAOK1','TAOK2','TAOK3','CRB1','CRB2','CRB3','LLGL1','LLGL2','HMCN1','HIPK2','FAT1','FAT2','FAT3','FAT4','DCHS1','DCHS2','CSNK1E','CSNK1D','AJUBA','LIMD1','WTIP','TGFBR1','TGFBR2','ACVR2A','ACVR1B','SMAD2','SMAD3','SMAD4','NFE2L2','KEAP1','CUL3') AND ((g.variant_type != 'cna' OR abs(g.cna_alteration) >= 2) AND NOT g.off_panel)
