  WHERE sp.cancer_study_identifier = 'msk_chord_2024'
    AND sp.alteration_type IN ('MUTATION_EXTENDED','COPY_NUMBER_ALTERATION','STRUCTURAL_VARIANT')
    AND replaceOne(sp.sample_unique_id, 'msk_chord_2024_', '') IN (SELECT sid FROM cohort)
),
per AS (
  SELECT members.set_name AS set_name, x.sid AS sid, max(x.is_alt) AS is_alt, max(x.is_drv) AS is_drv
  FROM (
    SELECT gene, sid, 1 AS is_alt, is_driver > 0 AS is_drv FROM altered
    UNION ALL
    SELECT gene, sid, 0 AS is_alt, 0 AS is_drv FROM covered
  ) x
  INNER JOIN members ON members.gene = x.gene
  GROUP BY set_name, sid
)
SELECT set_name, uniqExact(sid) AS profiled, uniqExactIf(sid, is_alt = 1) AS altered, uniqExactIf(sid, is_drv = 1) AS driver
FROM per GROUP BY set_name

